import unittest

from src.textutil import slugify


class SlugifyTests(unittest.TestCase):
    def test_lowercases(self):
        self.assertEqual(slugify("Hello"), "hello")

    def test_replaces_runs_with_single_dash(self):
        self.assertEqual(slugify("a  b!!c"), "a-b-c")

    def test_strips_leading_and_trailing_dashes(self):
        self.assertEqual(slugify("  --Hello World--  "), "hello-world")

    def test_keeps_digits(self):
        self.assertEqual(slugify("Top 10 Tips"), "top-10-tips")

    def test_non_ascii_is_replaced(self):
        self.assertEqual(slugify("café au lait"), "caf-au-lait")

    def test_empty_returns_untitled(self):
        self.assertEqual(slugify(""), "untitled")

    def test_only_symbols_returns_untitled(self):
        self.assertEqual(slugify("!!! ---"), "untitled")


if __name__ == "__main__":
    unittest.main()

